[CmdletBinding()]
param([Parameter(Mandatory=$true)][string]$ProjectRoot,[Parameter(Mandatory=$true)][string]$ManifestPath)
$ErrorActionPreference='Stop'; $root=(Resolve-Path $ProjectRoot).Path; $full=[IO.Path]::GetFullPath([IO.Path]::Combine($root,$ManifestPath)); if(-not(Test-Path $full -PathType Leaf)){throw 'Manifest missing'}; $m=Get-Content $full -Raw -Encoding UTF8|ConvertFrom-Json; $required=@('schemaVersion','skillName','sourceRoots','cases','staticClaims','runtimeClaimsNotProven','runtimeEscalation','caseAssertions','responsibilityProfile','responsibilityChecks','responsibilityScope');foreach($p in $required){if($null -eq $m.PSObject.Properties[$p]){throw "Missing manifest field: $p"}}; if(@($m.staticClaims).Count -eq 0){throw 'staticClaims must not be empty'}; if(@($m.responsibilityChecks).Count -eq 0){throw 'responsibilityChecks must not be empty'}; if([string]::IsNullOrWhiteSpace([string]$m.responsibilityScope)){throw 'responsibilityScope must not be empty'}; $cases=@($m.cases|ForEach-Object {[string]$_});foreach($c in @('normal-input','invalid-input','denied-expansion','repeat-idempotency','hash-change-cache-invalidation','interruption-recovery','deterministic-output')){if($cases -notcontains $c){throw "Missing static case: $c"};if([string]::IsNullOrWhiteSpace([string]$m.caseAssertions.$c)){throw "Missing case assertion: $c"}};Write-Output 'PASS: StaticDeepReplay manifest contract'
